/// Every dimension, in points, for one platform and density.
public struct NDMetrics: Sendable, Hashable {
    public let space0: Double
    public let space1: Double
    public let space2: Double
    public let space3: Double
    public let space4: Double
    public let space6: Double
    public let space8: Double
    public let space12: Double
    public let space16: Double
    public let space24: Double
    public let rhythm1: Double
    public let rhythm2: Double
    public let rhythm3: Double
    public let rhythm4: Double
    public let rhythm5: Double
    public let rhythm10: Double
    public let radiusSm: Double
    public let radiusMd: Double
    public let radiusLg: Double
    public let radiusXl: Double
    public let radius2xl: Double
    public let radiusPill: Double
    public let sizeIcon: Double
    public let sizeIconMd: Double
    public let sizeIconLg: Double
    public let sizeBrand: Double
    public let sizeHomeArtMax: Double
    public let sizeHomeArtCenteredMax: Double
    public let sizeFeaturedCardMin: Double
    public let sizeDirectionCardMin: Double
    public let sizeDockTile: Double
    public let sizeDockIcon: Double
    public let sizeDockMax: Double
    /// A 3 px pip and lane.
    public let markPip: Double
    /// The small dot and its 5 px lane: kickers, the page bar, rails.
    public let markDot: Double
    /// A 9 px node on a time line.
    public let markNode: Double
    /// The 15 px dot at a heading's, a rail's or a foot's end.
    public let markDotLg: Double
    /// The stroke of drawn controls: a menu's bars, a chevron, a disclosure's plus.
    public let markStroke: Double
    public let borderWidthNone: Double
    public let borderWidthThin: Double
    public let borderWidthMedium: Double
    public let borderWidthThick: Double
    /// Focus outline width (WCAG 2.2 2.4.13: at least a 2 px perimeter).
    public let focusWidth: Double
    /// Space between a control and its focus outline, filled with surface.base.
    public let focusGap: Double
    public let sizeControlSm: Double
    public let sizeControlMd: Double
    public let sizeControlLg: Double
    public let sizeField: Double
    public let sizeTargetMin: Double
}

extension NDMetrics {
    public static func resolve(platform: NDPlatform, density: NDDensity) -> NDMetrics {
        switch (platform, density) {
        case (.ios, .comfortable): return metrics_ios_comfortable()
        case (.ios, .compact): return metrics_ios_compact()
        case (.android, .comfortable): return metrics_android_comfortable()
        case (.android, .compact): return metrics_android_compact()
        case (.desktop, .comfortable): return metrics_desktop_comfortable()
        case (.desktop, .compact): return metrics_desktop_compact()
        }
    }

