/// Numbers: opacity, leading, tracking (em), stacking, springs.
public enum NDNumbers {
    /// A disabled control (WCAG exempts it from contrast).
    public static let opacityDisabled: Double = 0.4
    public static let opacityMuted: Double = 0.6
    public static let opacitySubtle: Double = 0.16
    /// Scrim behind a dialog.
    public static let opacityOverlay: Double = 0.55
    public static let textLeadingDisplay: Double = 1.06
    public static let textLeadingH1: Double = 1.1
    public static let textLeadingH2: Double = 1.15
    public static let textLeadingH3: Double = 1.22
    public static let textLeadingH4: Double = 1.3
    public static let textLeadingBodyLg: Double = 1.55
    public static let textLeadingBody: Double = 1.6
    public static let textLeadingLabel: Double = 1.4
    public static let textLeadingCaption: Double = 1.3
    public static let scriptLeadingAr: Double = 1.8
    public static let scriptLeadingZh: Double = 1.75
    /// Display headings.
    public static let trackingTight: Double = -0.02 // em
    public static let trackingSnug: Double = -0.01 // em
    public static let trackingNormal: Double = 0.0 // em
    public static let trackingLoose: Double = 0.02 // em
    public static let trackingWide: Double = 0.04 // em
    /// Upper-case labels and kickers.
    public static let trackingWider: Double = 0.06 // em
    public static let springStandardStiffness: Double = 380.0
    public static let springStandardDampingRatio: Double = 0.8
    public static let springGentleStiffness: Double = 200.0
    public static let springGentleDampingRatio: Double = 1.0
    public static let springSnappyStiffness: Double = 700.0
    public static let springSnappyDampingRatio: Double = 0.9
    public static let zBase: Double = 0.0
    public static let zRaised: Double = 10.0
    public static let zSticky: Double = 100.0
    public static let zOverlay: Double = 200.0
    public static let zDialog: Double = 300.0
    public static let zToast: Double = 400.0
    public static let zSkip: Double = 1000.0
    public static let artGlow: Double = 0.4
}

/// Font weights (1...1000).
public enum NDWeights {
    public static let weightRegular: Int = 400
    public static let weightMedium: Int = 500
    public static let weightSemibold: Int = 600
}

/// Font families per platform, most preferred first.
public enum NDFonts {
    public static func stack(_ family: NDFontFamily, _ platform: NDPlatform) -> [String] {
        switch (family, platform) {
        case (.sans, .ios): return ["IBM Plex Sans", ".AppleSystemUIFont"]
        case (.sans, .android): return ["IBM Plex Sans", "Roboto"]
        case (.sans, .desktop): return ["IBM Plex Sans", "IBM Plex Sans Fallback", "system-ui", "-apple-system", "Segoe UI", "Roboto", "Helvetica Neue", "Arial", "sans-serif"]
        case (.sansAr, .ios): return ["IBM Plex Sans Arabic", ".AppleSystemUIFont"]
        case (.sansAr, .android): return ["IBM Plex Sans Arabic", "Noto Sans Arabic"]
        case (.sansAr, .desktop): return ["IBM Plex Sans Arabic", "IBM Plex Sans", "IBM Plex Sans Fallback", "system-ui", "Segoe UI", "Tahoma", "Arial", "sans-serif"]
        case (.sansZh, .ios): return ["PingFang SC"]
        case (.sansZh, .android): return ["Noto Sans CJK SC"]
        case (.sansZh, .desktop): return ["IBM Plex Sans", "Noto Sans SC", "IBM Plex Sans Fallback", "system-ui", "PingFang SC", "Microsoft YaHei", "sans-serif"]
        case (.mono, .ios): return ["SF Mono", "Menlo"]
        case (.mono, .android): return ["monospace"]
        case (.mono, .desktop): return ["ui-monospace", "SFMono-Regular", "Menlo", "Consolas", "Liberation Mono", "monospace"]
        }
    }
}

/// Durations in seconds.
public enum NDDurations {
    public static func durationUiFast(_ motion: NDMotion) -> Double {
        switch motion {
        case .standard: return 0.15
        case .reduced: return 0.0
        }
    }
    public static func durationUi(_ motion: NDMotion) -> Double {
        switch motion {
        case .standard: return 0.25
        case .reduced: return 0.0
        }
    }
    public static func durationScene(_ motion: NDMotion) -> Double {
        switch motion {
        case .standard: return 0.45
        case .reduced: return 0.0
        }
    }
    public static func durationSceneSlow(_ motion: NDMotion) -> Double {
        switch motion {
        case .standard: return 0.9
        case .reduced: return 0.0
        }
    }
}

/// A cubic Bezier easing: control points (x1, y1, x2, y2).
public struct NDEasing: Sendable, Hashable {
    public let x1: Double
    public let y1: Double
    public let x2: Double
    public let y2: Double

    public init(_ x1: Double, _ y1: Double, _ x2: Double, _ y2: Double) {
        self.x1 = x1
        self.y1 = y1
        self.x2 = x2
        self.y2 = y2
    }
}

public enum NDEasings {
    /// The standard easing of interface motion.
    public static let easing = NDEasing(0.2, 0.7, 0.2, 1.0)
    /// Decelerate: something arriving.
    public static let easingEnter = NDEasing(0.0, 0.0, 0.2, 1.0)
    /// Accelerate: something leaving.
    public static let easingExit = NDEasing(0.4, 0.0, 1.0, 1.0)
    /// A larger, more noticeable change.
    public static let easingEmphasized = NDEasing(0.2, 0.0, 0.0, 1.0)
}

/// One layer of a shadow, in points.
public struct NDShadowLayer: Sendable, Hashable {
    public let color: NDColor
    public let x: Double
    public let y: Double
    public let blur: Double
    public let spread: Double
    public let inset: Bool
}

public enum NDShadows {
    public static func elevation1(_ theme: NDTheme) -> [NDShadowLayer] {
        switch theme {
        case .light: return [NDShadowLayer(color: NDColor(rgba: 0x0000001F), x: 0.0, y: 1.0, blur: 3.0, spread: 0.0, inset: false)]
        case .dark: return [NDShadowLayer(color: NDColor(rgba: 0x00000099), x: 0.0, y: 1.0, blur: 2.0, spread: 0.0, inset: false)]
        case .lightContrast: return [NDShadowLayer(color: NDColor(rgba: 0x0000001F), x: 0.0, y: 1.0, blur: 3.0, spread: 0.0, inset: false)]
        case .darkContrast: return [NDShadowLayer(color: NDColor(rgba: 0x00000099), x: 0.0, y: 1.0, blur: 2.0, spread: 0.0, inset: false)]
        }
    }
    public static func elevation2(_ theme: NDTheme) -> [NDShadowLayer] {
        switch theme {
        case .light: return [NDShadowLayer(color: NDColor(rgba: 0x0000001F), x: 0.0, y: 6.0, blur: 16.0, spread: 0.0, inset: false)]
        case .dark: return [NDShadowLayer(color: NDColor(rgba: 0x000000B3), x: 0.0, y: 4.0, blur: 12.0, spread: 0.0, inset: false)]
        case .lightContrast: return [NDShadowLayer(color: NDColor(rgba: 0x0000001F), x: 0.0, y: 6.0, blur: 16.0, spread: 0.0, inset: false)]
        case .darkContrast: return [NDShadowLayer(color: NDColor(rgba: 0x000000B3), x: 0.0, y: 4.0, blur: 12.0, spread: 0.0, inset: false)]
        }
    }
    public static func elevation3(_ theme: NDTheme) -> [NDShadowLayer] {
        switch theme {
        case .light: return [NDShadowLayer(color: NDColor(rgba: 0x00000029), x: 0.0, y: 16.0, blur: 40.0, spread: 0.0, inset: false)]
        case .dark: return [NDShadowLayer(color: NDColor(rgba: 0x000000CC), x: 0.0, y: 12.0, blur: 32.0, spread: 0.0, inset: false)]
        case .lightContrast: return [NDShadowLayer(color: NDColor(rgba: 0x00000029), x: 0.0, y: 16.0, blur: 40.0, spread: 0.0, inset: false)]
        case .darkContrast: return [NDShadowLayer(color: NDColor(rgba: 0x000000CC), x: 0.0, y: 12.0, blur: 32.0, spread: 0.0, inset: false)]
        }
    }
}

/// A text style on a platform: family, size in points, line height as a multiple of the size,
/// weight, letter spacing as a share of the size (em), case, and the Dynamic Type style it scales
/// with.
public struct NDTextStyle: Sendable, Hashable {
    public let family: NDFontFamily
    public let size: Double
    public let lineHeight: Double
    public let weight: Int
    public let tracking: Double
    public let uppercase: Bool
    public let dynamicType: String?

    /// Letter spacing in points.
    public var trackingPoints: Double { tracking * size }
}

extension NDTextStyle {
    /// The style of a role on a platform, adjusted for the script of the text.
    public static func resolve(
        _ role: NDTypeRole,
        platform: NDPlatform,
        script: NDScript = .latin
    ) -> NDTextStyle {
        let base = base(role, platform)
        return NDTextStyle(
            family: base.family == .sans ? script.family : base.family,
            size: base.size,
            lineHeight: role.isBody ? (script.bodyLeading ?? base.lineHeight) : base.lineHeight,
            weight: base.weight,
            tracking: script.tracksLetters ? base.tracking : 0,
            uppercase: script.hasCase && base.uppercase,
            dynamicType: base.dynamicType
        )
    }

    static func base(_ role: NDTypeRole, _ platform: NDPlatform) -> NDTextStyle {
        switch (role, platform) {
        case (.display, .ios): return NDTextStyle(family: .sans, size: 34.0, lineHeight: 1.06, weight: 400, tracking: -0.02, uppercase: false, dynamicType: "largeTitle")
        case (.display, .android): return NDTextStyle(family: .sans, size: 36.0, lineHeight: 1.06, weight: 400, tracking: -0.02, uppercase: false, dynamicType: "largeTitle")
        case (.display, .desktop): return NDTextStyle(family: .sans, size: 40.0, lineHeight: 1.06, weight: 400, tracking: -0.02, uppercase: false, dynamicType: "largeTitle")
        case (.h1, .ios): return NDTextStyle(family: .sans, size: 28.0, lineHeight: 1.1, weight: 400, tracking: -0.01, uppercase: false, dynamicType: "title")
        case (.h1, .android): return NDTextStyle(family: .sans, size: 32.0, lineHeight: 1.1, weight: 400, tracking: -0.01, uppercase: false, dynamicType: "title")
        case (.h1, .desktop): return NDTextStyle(family: .sans, size: 32.0, lineHeight: 1.1, weight: 400, tracking: -0.01, uppercase: false, dynamicType: "title")
        case (.h2, .ios): return NDTextStyle(family: .sans, size: 22.0, lineHeight: 1.15, weight: 400, tracking: -0.01, uppercase: false, dynamicType: "title2")
        case (.h2, .android): return NDTextStyle(family: .sans, size: 28.0, lineHeight: 1.15, weight: 400, tracking: -0.01, uppercase: false, dynamicType: "title2")
        case (.h2, .desktop): return NDTextStyle(family: .sans, size: 28.0, lineHeight: 1.15, weight: 400, tracking: -0.01, uppercase: false, dynamicType: "title2")
        case (.h3, .ios): return NDTextStyle(family: .sans, size: 20.0, lineHeight: 1.22, weight: 400, tracking: -0.01, uppercase: false, dynamicType: "title3")
        case (.h3, .android): return NDTextStyle(family: .sans, size: 24.0, lineHeight: 1.22, weight: 400, tracking: -0.01, uppercase: false, dynamicType: "title3")
        case (.h3, .desktop): return NDTextStyle(family: .sans, size: 22.0, lineHeight: 1.22, weight: 400, tracking: -0.01, uppercase: false, dynamicType: "title3")
        case (.h4, .ios): return NDTextStyle(family: .sans, size: 17.0, lineHeight: 1.3, weight: 400, tracking: -0.01, uppercase: false, dynamicType: "headline")
        case (.h4, .android): return NDTextStyle(family: .sans, size: 22.0, lineHeight: 1.3, weight: 400, tracking: -0.01, uppercase: false, dynamicType: "headline")
        case (.h4, .desktop): return NDTextStyle(family: .sans, size: 18.0, lineHeight: 1.3, weight: 400, tracking: -0.01, uppercase: false, dynamicType: "headline")
        case (.lead, .ios): return NDTextStyle(family: .sans, size: 17.0, lineHeight: 1.55, weight: 400, tracking: 0.0, uppercase: false, dynamicType: "body")
        case (.lead, .android): return NDTextStyle(family: .sans, size: 16.0, lineHeight: 1.55, weight: 400, tracking: 0.0, uppercase: false, dynamicType: "body")
        case (.lead, .desktop): return NDTextStyle(family: .sans, size: 16.0, lineHeight: 1.55, weight: 400, tracking: 0.0, uppercase: false, dynamicType: "body")
        case (.body, .ios): return NDTextStyle(family: .sans, size: 16.0, lineHeight: 1.6, weight: 400, tracking: 0.0, uppercase: false, dynamicType: "callout")
        case (.body, .android): return NDTextStyle(family: .sans, size: 14.0, lineHeight: 1.6, weight: 400, tracking: 0.0, uppercase: false, dynamicType: "callout")
        case (.body, .desktop): return NDTextStyle(family: .sans, size: 14.0, lineHeight: 1.6, weight: 400, tracking: 0.0, uppercase: false, dynamicType: "callout")
        case (.label, .ios): return NDTextStyle(family: .sans, size: 15.0, lineHeight: 1.4, weight: 400, tracking: 0.0, uppercase: false, dynamicType: "subheadline")
        case (.label, .android): return NDTextStyle(family: .sans, size: 14.0, lineHeight: 1.4, weight: 400, tracking: 0.0, uppercase: false, dynamicType: "subheadline")
        case (.label, .desktop): return NDTextStyle(family: .sans, size: 13.0, lineHeight: 1.4, weight: 400, tracking: 0.0, uppercase: false, dynamicType: "subheadline")
        case (.kicker, .ios): return NDTextStyle(family: .sans, size: 15.0, lineHeight: 1.4, weight: 400, tracking: 0.06, uppercase: true, dynamicType: "subheadline")
        case (.kicker, .android): return NDTextStyle(family: .sans, size: 14.0, lineHeight: 1.4, weight: 400, tracking: 0.06, uppercase: true, dynamicType: "subheadline")
        case (.kicker, .desktop): return NDTextStyle(family: .sans, size: 13.0, lineHeight: 1.4, weight: 400, tracking: 0.06, uppercase: true, dynamicType: "subheadline")
        case (.caption, .ios): return NDTextStyle(family: .sans, size: 12.0, lineHeight: 1.3, weight: 400, tracking: 0.0, uppercase: false, dynamicType: "caption")
        case (.caption, .android): return NDTextStyle(family: .sans, size: 12.0, lineHeight: 1.3, weight: 400, tracking: 0.0, uppercase: false, dynamicType: "caption")
        case (.caption, .desktop): return NDTextStyle(family: .sans, size: 12.0, lineHeight: 1.3, weight: 400, tracking: 0.0, uppercase: false, dynamicType: "caption")
        case (.code, .ios): return NDTextStyle(family: .mono, size: 15.2, lineHeight: 1.6, weight: 400, tracking: 0.0, uppercase: false, dynamicType: "callout")
        case (.code, .android): return NDTextStyle(family: .mono, size: 13.3, lineHeight: 1.6, weight: 400, tracking: 0.0, uppercase: false, dynamicType: "callout")
        case (.code, .desktop): return NDTextStyle(family: .mono, size: 13.3, lineHeight: 1.6, weight: 400, tracking: 0.0, uppercase: false, dynamicType: "callout")
        }
    }
}
